/** Workspace root folder icon (upstream's `rootFolder`). */
export const ROOT_FOLDER_ICON = 'folder-root';

/** Resolved icon for a file name: exact filename first, then extension. */
export function getMaterialIcon(name: string): string {
  const lower = name.toLowerCase();

  // 1. Exact filename (readme.md, security.md, vite.config.ts, ...) — like
  //    the extension's fileNames layer, which always wins over extensions,
  //    so README.md gets its own icon instead of the generic markdown one.
  const byFilename = MATERIAL_FILENAME_MAP[lower];
  if (byFilename) return byFilename;

  // 2. Extension fallback — try dotted suffixes from longest to shortest so
  //    compound extensions win over the bare last segment (foo.svelte.ts ->
  //    svelte_ts, Comp.stories.svelte -> storybook, utils.spec.ts -> test-ts,
  //    types.d.ts -> typescript-def), exactly like VSCode's association rules.
  const firstDot = lower.indexOf('.');
  if (firstDot !== -1) {
    for (let i = firstDot; i !== -1; i = lower.indexOf('.', i + 1)) {
      const hit = MATERIAL_FILE_MAP[lower.slice(i + 1)];
      if (hit) return hit;
    }
  }

  // 3. Bare-name fallback for extension-less files (docker, jakefile, ...)
  return MATERIAL_FILE_MAP[lower] ?? 'document';
}

/** Resolved folder icon (sans `folder-` prefix); falls back to `base`. */
export function getMaterialFolderIcon(name: string): string {
  return MATERIAL_FOLDER_MAP[name.toLowerCase()] ?? 'base';
}
